<?php
declare(strict_types=1);
namespace DigiForge\Tests;
use PHPUnit\Framework\TestCase;
use DigiForge\POD\{PrintifyAcceptanceBinding as Normal,PrintifyAcceptanceDraftBinding as Draft};
require_once __DIR__.'/../../includes/POD/PrintifyAcceptanceBinding.php';
if(is_file(__DIR__.'/../../includes/POD/PrintifyAcceptanceDraftBinding.php'))require_once __DIR__.'/../../includes/POD/PrintifyAcceptanceDraftBinding.php';
final class PrintifyAcceptanceDraftBindingTest extends TestCase {
 private function evidence():array {return ['account_association_verified'=>true,'account_reference'=>'synthetic-account','credential_reference_present'=>true,'credential_metadata_sha256'=>str_repeat('a',64),'credential_account_association_verified'=>true,'registry_scope_verified'=>true,'duplicate_mapping'=>false,'cross_shop_conflict'=>false,'provider_scope_verified'=>true,'integration_enabled'=>false,'evidence_revision'=>2,'approval_sha256'=>str_repeat('b',64),'independent_approval_valid'=>true,'authority_revoked'=>false];}
 private function proposal():array {self::assertTrue(class_exists(Draft::class),'Separate inactive acceptance binding contract required');$p=Draft::proposal();$p['normal_binding']=array_replace($p['normal_binding'],['account_reference'=>'synthetic-account','credential_reference'=>['integration_id'=>3,'secret_name'=>'personal_access_token','metadata_sha256'=>str_repeat('a',64)],'catalog_scope'=>['business_id'=>1,'store_id'=>2,'product_program'=>'PERSONALIZED_POD'],'evidence_revision'=>2,'approval_sha256'=>str_repeat('b',64),'observed_at'=>1000,'expires_at'=>1300]);return $p;}
 public function testDisabledDraftIsConsistentButNormalRuntimeStillDenied():void {$p=$this->proposal();$e=$this->evidence();$r=Draft::validate($p,$e,1100);self::assertSame('OFFLINE_VERIFIED',$r['identity_validation']);self::assertSame([],$r['identity_blockers']);self::assertContains('INTEGRATION_DISABLED_OR_UNKNOWN',$r['normal_runtime_validation']['blockers']);self::assertSame('POLICY_AMENDMENT_REQUIRED',$r['status']);self::assertFalse($r['runtime_execution_authorized']);self::assertFalse($r['binding_write_authorized']);self::assertContains('INTEGRATION_DISABLED_OR_UNKNOWN',Normal::validate($p['normal_binding'],$e,1100)['blockers']);}
 public function testEnabledIntegrationCannotBePresentedAsDisabledDraft():void {$p=$this->proposal();$e=$this->evidence();$e['integration_enabled']=true;$p['normal_binding']['integration_enabled']=true;$r=Draft::validate($p,$e,1100);self::assertContains('DRAFT_REQUIRES_DISABLED_INTEGRATION',$r['identity_blockers']);self::assertFalse($r['runtime_execution_authorized']);}
 public function testUnknownAssociationAndWrongShopRemainBlocked():void {$p=$this->proposal();$e=$this->evidence();$e['credential_account_association_verified']=false;$p['normal_binding']['provider_shop_id']='28925875';$r=Draft::validate($p,$e,1100);self::assertContains('CREDENTIAL_ACCOUNT_ASSOCIATION_UNKNOWN',$r['identity_blockers']);self::assertContains('PROVIDER_SHOP_MISMATCH',$r['identity_blockers']);}
 public function testAdoptedAndMalformedDraftCannotGrantAuthority():void {$p=$this->proposal();$p['adoption_status']='ADOPTED';$r=Draft::validate($p,$this->evidence(),1100);self::assertContains('INVALID_INACTIVE_DRAFT',$r['identity_blockers']);self::assertFalse($r['runtime_execution_authorized']);unset($p['normal_binding']);self::assertContains('INVALID_INACTIVE_DRAFT',Draft::validate($p,[],1100)['identity_blockers']);}
 public function testExpiredRevokedConflictingEvidenceIsPreserved():void {$p=$this->proposal();$p['normal_binding']['expires_at']=1050;$e=array_replace($this->evidence(),['authority_revoked'=>true,'duplicate_mapping'=>true,'cross_shop_conflict'=>true]);$r=Draft::validate($p,$e,1100);foreach(['STALE_OR_EXPIRED_EVIDENCE','REVOKED_OR_UNKNOWN_AUTHORITY','DUPLICATE_MAPPING_OR_UNKNOWN','CROSS_SHOP_CONFLICT_OR_UNKNOWN'] as $reason)self::assertContains($reason,$r['identity_blockers']);}
 public function testUnknownAndStringEnablementAreNotClassifiedAsKnownDisabled():void {$p=$this->proposal();foreach([null,'false',0] as $v){$e=$this->evidence();$e['integration_enabled']=$v;$r=Draft::validate($p,$e,1100);self::assertContains('DRAFT_REQUIRES_DISABLED_INTEGRATION',$r['identity_blockers']);self::assertContains('INTEGRATION_DISABLED_OR_UNKNOWN',$r['identity_blockers']);self::assertFalse($r['runtime_execution_authorized']);}}

}
